  await a.click('#sidebar-toggle'); await again();
  same(`nothing cut off at 860×560 with the sidebar open: ${where}`, [...await a.run(CUT_OFF), ...await a.run(SIDEBAR_CUT)], []);
  await a.click('#sidebar-toggle');
