  writeFileSync(join(tools, '.local/bin/claude'), '#!/bin/sh\n[ "$1" = "--version" ] && echo "2.1.322 (Claude Code)" && exit 0\nexit 9\n', { mode: 0o755 });
  mkdirSync(data, { recursive: true });
